#!/usr/bin/env python3
"""Clean-room reimplementation of the observed jplot executable.

This intentionally uses only the Python standard library.  It implements the
observable command-line interface, JSON metric extraction, terminal setup, and
inline iTerm2 PNG rendering protocol used by the benchmark binary.
"""
import base64
import errno
import json
import math
import os
import re
import signal
import struct
import sys
import time
import urllib.error
import urllib.request
import zlib
from typing import Any, Dict, List, Tuple

USAGE = """Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:

OPTIONS:
  -interval duration
    	When url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval. (default 1s)
  -rows int
    	Limits the height of the graph output.
  -steps int
    	Number of values to plot. (default 100)
  -url string
    	URL to fetch every second. Read JSON objects from stdin if not specified.

FIELD_SPEC: [<option>[,<option>...]:]path
  option:
    - counter: Computes the difference with the last value. The value must increase monotonically.
    - marker: When the value is none-zero, a vertical line is drawn.
  path:
    JSON field path (eg: field.sub-field).
"""

GRAPHICS_ERR = "iTerm2, Kitty, or DRCS Sixel graphics required"

# Colours used by the lightweight renderer.  The exact plot pixels of the
# original are not part of the terminal protocol; this provides stable graphs.
PALETTE = [
    (31, 119, 180, 255),
    (255, 127, 14, 255),
    (44, 160, 44, 255),
    (214, 39, 40, 255),
    (148, 103, 189, 255),
    (140, 86, 75, 255),
    (227, 119, 194, 255),
    (127, 127, 127, 255),
]

running = True


def on_term(signum, frame):  # pragma: no cover - signal path
    global running
    running = False


signal.signal(signal.SIGTERM, on_term)
signal.signal(signal.SIGINT, on_term)


def bwrite(data: bytes) -> None:
    try:
        sys.stdout.buffer.write(data)
        sys.stdout.buffer.flush()
    except BrokenPipeError:
        sys.exit(1)


def swrite(text: str) -> None:
    bwrite(text.encode())


def ewrite(text: str) -> None:
    try:
        sys.stderr.write(text)
        sys.stderr.flush()
    except BrokenPipeError:
        sys.exit(1)


class FlagError(Exception):
    pass


class HelpRequested(Exception):
    pass


class DataError(Exception):
    pass


class RenderError(Exception):
    pass


class Options:
    def __init__(self) -> None:
        self.interval_text = "1s"
        self.interval = 1.0
        self.rows = 0
        self.steps = 100
        self.url = ""


def parse_int_value(flag: str, value: str) -> int:
    # Go's flag package reports "parse error" for bad ints in this program.
    if not re.fullmatch(r"[+-]?\d+", value or ""):
        raise FlagError(f'invalid value "{value}" for flag -{flag}: parse error')
    try:
        return int(value, 10)
    except Exception:
        raise FlagError(f'invalid value "{value}" for flag -{flag}: parse error')


_DUR_RE = re.compile(r"([+-]?(?:\d+(?:\.\d*)?|\.\d+))(ns|us|µs|μs|ms|s|m|h)")
_DUR_MULT = {
    "ns": 1e-9,
    "us": 1e-6,
    "µs": 1e-6,
    "μs": 1e-6,
    "ms": 1e-3,
    "s": 1.0,
    "m": 60.0,
    "h": 3600.0,
}


def parse_duration(flag: str, value: str) -> float:
    # A compact approximation of Go's time.ParseDuration for validation and
    # sleeping.  It accepts signs and concatenated unit terms (e.g. 1m2.5s).
    if value == "":
        raise FlagError(f'invalid value "{value}" for flag -{flag}: parse error')
    sign = 1.0
    s = value
    if s[0] in "+-":
        if s[0] == "-":
            sign = -1.0
        s = s[1:]
    pos = 0
    total = 0.0
    if not s:
        raise FlagError(f'invalid value "{value}" for flag -{flag}: parse error')
    while pos < len(s):
        m = _DUR_RE.match(s, pos)
        if not m:
            raise FlagError(f'invalid value "{value}" for flag -{flag}: parse error')
        num, unit = m.groups()
        try:
            total += float(num) * _DUR_MULT[unit]
        except Exception:
            raise FlagError(f'invalid value "{value}" for flag -{flag}: parse error')
        pos = m.end()
    return sign * total


def parse_flags(argv: List[str]) -> Tuple[Options, List[str]]:
    opts = Options()
    args: List[str] = []
    i = 0
    flag_names = {"interval", "rows", "steps", "url"}
    while i < len(argv):
        tok = argv[i]
        if tok == "--":
            args.extend(argv[i + 1 :])
            break
        if tok == "-" or not tok.startswith("-"):
            args.extend(argv[i:])
            break
        # Go flag accepts one or two leading minuses.
        raw = tok[2:] if tok.startswith("--") else tok[1:]
        name: str
        value = None
        if "=" in raw:
            name, value = raw.split("=", 1)
        else:
            name = raw
        if name in ("h", "help"):
            raise HelpRequested()
        if name not in flag_names:
            raise FlagError(f"flag provided but not defined: -{name}")
        if value is None:
            if i + 1 >= len(argv):
                raise FlagError(f"flag needs an argument: -{name}")
            value = argv[i + 1]
            i += 1
        if name == "steps":
            opts.steps = parse_int_value(name, value)
        elif name == "rows":
            opts.rows = parse_int_value(name, value)
        elif name == "interval":
            opts.interval_text = value
            opts.interval = parse_duration(name, value)
        elif name == "url":
            opts.url = value
        i += 1
    return opts, args


class Field:
    def __init__(self, path: str, counter: bool = False, marker: bool = False) -> None:
        self.path = path
        self.counter = counter
        self.marker = marker
        self.prev = None  # type: Any
        self.values: List[float] = []
        self.marks: List[bool] = []

    @property
    def is_series(self) -> bool:
        # Observed behavior: a field with marker is not plotted as a series,
        # even if counter is also specified.
        return not self.marker


class Graph:
    def __init__(self, fields: List[Field]) -> None:
        self.fields = fields


def parse_specs(args: List[str]) -> List[Graph]:
    graphs: List[Graph] = []
    for arg in args:
        fields: List[Field] = []
        for part in arg.split("+"):
            counter = False
            marker = False
            path = part
            if ":" in part:
                opt_text, path = part.split(":", 1)
                for opt in opt_text.split(","):
                    if opt == "counter":
                        counter = True
                    elif opt == "marker":
                        marker = True
                    else:
                        raise ValueError(f"invalid field option: {opt}")
            fields.append(Field(path, counter=counter, marker=marker))
        graphs.append(Graph(fields))
    return graphs


def go_type_name(v: Any) -> str:
    if v is None:
        return "<nil>"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, str):
        return "string"
    if isinstance(v, list):
        return "[]interface {}"
    if isinstance(v, dict):
        return "map[string]interface {}"
    if isinstance(v, (int, float)):
        return "float64"
    return type(v).__name__


def extract_path(obj: Any, path: str) -> float:
    cur = obj
    if path != "":
        for part in path.split("."):
            if not isinstance(cur, dict):
                raise DataError(f"cannot get {path}: {part} is not an object. map[]")
            if part not in cur:
                raise DataError(f"cannot get {path}: {part} does not exist.")
            cur = cur[part]
    # Go's json decoder yields float64 for all numbers; bools are separate.
    if isinstance(cur, bool) or not isinstance(cur, (int, float)):
        raise DataError(f"invalid type {path}: {go_type_name(cur)}")
    return float(cur)


def json_error_message(text: str, exc: Exception, stream: bool) -> str:
    stripped = text.lstrip()
    if stripped == "":
        return "unexpected end of JSON input"
    # Match the common Go encoding/json diagnostics observed in the binary.
    if stripped.startswith("not"):
        return "invalid character 'o' in literal null (expecting 'u')"
    if stripped.startswith("nul") and not stripped.startswith("null"):
        return "invalid character %r in literal null (expecting 'l')" % (stripped[2] if len(stripped) > 2 else " ")
    # Multiple top-level JSON values without newline in a single input record.
    dec = json.JSONDecoder()
    try:
        _, end = dec.raw_decode(stripped)
        rest = stripped[end:].lstrip()
        if rest:
            return f"invalid character {rest[0]!r} after top-level value"
    except Exception:
        pass
    # A few common first-character forms from Go's scanner.
    ch = stripped[0]
    if ch == "'":
        return "invalid character '\'' looking for beginning of value"
    if ch not in "{[\"-0123456789tfn":
        return f"invalid character {ch!r} looking for beginning of value"
    # Fall back to Python's message when no observed Go equivalent is known.
    msg = str(exc)
    if "Extra data" in msg:
        # Locate the extra byte if possible.
        try:
            _, end = json.JSONDecoder().raw_decode(stripped)
            rest = stripped[end:].lstrip()
            if rest:
                return f"invalid character {rest[0]!r} after top-level value"
        except Exception:
            pass
    if "Unterminated string" in msg:
        return "unexpected end of JSON input"
    if "Expecting value" in msg and stripped == "":
        return "unexpected end of JSON input"
    return msg


def parse_json_record(text: str, stream: bool = False) -> Any:
    try:
        dec = json.JSONDecoder()
        obj, end = dec.raw_decode(text.lstrip())
        rest = text.lstrip()[end:].strip()
        if rest:
            raise json.JSONDecodeError("Extra data", text, end)
        return obj
    except Exception as e:
        raise DataError("input error: " + json_error_message(text, e, stream))


def apply_object(graphs: List[Graph], obj: Any, steps: int, interval: float) -> None:
    for g in graphs:
        for f in g.fields:
            val = extract_path(obj, f.path)
            out = val
            if f.counter:
                if f.prev is None:
                    out = 0.0
                else:
                    out = val - float(f.prev)
                    # The README says URL counters are based on the interval;
                    # keep the difference when interval is zero/negative.
                    if interval and interval > 0:
                        # The original plots a rate for counters fetched at a
                        # fixed interval.  For stdin this only affects pixels.
                        out = out / interval
                f.prev = val
            if f.marker:
                f.marks.append(bool(out))
                if len(f.marks) > max(0, steps):
                    del f.marks[0 : len(f.marks) - max(0, steps)]
            else:
                f.values.append(float(out))
                if len(f.values) > max(0, steps):
                    del f.values[0 : len(f.values) - max(0, steps)]


def process_stdin_records(graphs: List[Graph], opts: Options) -> None:
    # The original accepts newline-delimited JSON records from stdin.  A line
    # containing two adjacent top-level objects is an error.
    for raw in sys.stdin:
        line = raw.rstrip("\n")
        if line == "" and raw == "":
            continue
        if line == "":
            # Blank lines are invalid JSON records in the observed pipeline.
            obj = parse_json_record(line, stream=True)
        else:
            obj = parse_json_record(line, stream=True)
        apply_object(graphs, obj, opts.steps, opts.interval)


def fetch_url_once(url: str) -> Any:
    if not re.match(r"^[A-Za-z][A-Za-z0-9+.-]*://", url or ""):
        raise DataError(f'input error: parse "{url}": missing protocol scheme')
    try:
        with urllib.request.urlopen(url, timeout=5) as resp:
            data = resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        # Go's http.Get returns a response for HTTP error status; the program
        # then decodes the body, so do the same.
        try:
            data = e.read().decode("utf-8", "replace")
        except Exception:
            raise DataError(f"input error: {e}")
    except Exception as e:
        # Python and Go format network errors differently.  Shape the common
        # connection-refused case like Go where possible.
        msg = str(e)
        if "Connection refused" in msg or "Errno 111" in msg:
            m = re.match(r"http://([^/]+)(/.*)?", url)
            host = m.group(1) if m else url
            path = m.group(2) if m and m.group(2) else ""
            raise DataError(f'input error: Get "{url}": dial tcp {host}: connect: connection refused')
        raise DataError(f"input error: {msg}")
    return parse_json_record(data, stream=False)


def terminal_supported() -> Tuple[bool, str]:
    # The observed binary recognizes exactly TERM_PROGRAM=iTerm.app without an
    # initial DA query.  Otherwise it writes ESC[c while probing, then later
    # reports unsupported graphics if execution reaches rendering.
    if os.environ.get("TERM_PROGRAM") == "iTerm.app":
        return True, "iterm"
    bwrite(b"\x1b[c")
    return False, GRAPHICS_ERR


def get_terminal_size_or_error() -> Tuple[int, int]:
    try:
        sz = os.get_terminal_size(sys.stdout.fileno())
        return sz.columns, sz.lines
    except OSError:
        raise RenderError("Cannot get window size:  inappropriate ioctl for device")


def read_iterm_cell_size() -> Tuple[float, float]:
    # Query was already written.  Read terminal response from /dev/tty, because
    # stdin may be the JSON pipe.  Response format observed/used by iTerm:
    #   ESC ] 1337;ReportCellSize=<height>;<width> BEL
    fd = None
    old_attrs = None
    try:
        fd = os.open("/dev/tty", os.O_RDWR | os.O_NOCTTY)
        try:
            import termios
            import tty

            old_attrs = termios.tcgetattr(fd)
            tty.setraw(fd)
        except Exception:
            old_attrs = None
        os.set_blocking(fd, False)
        deadline = time.time() + 1.0
        data = b""
        while time.time() < deadline:
            try:
                chunk = os.read(fd, 256)
                if chunk:
                    data += chunk
                    if b"\x07" in data or b"\x1b\\" in data:
                        break
            except BlockingIOError:
                pass
            except OSError:
                break
            time.sleep(0.01)
        m = re.search(br"ReportCellSize=([0-9.]+);([0-9.]+)", data)
        if not m:
            raise RenderError("Cannot get window size:  cannot get terminal cell size")
        ch = float(m.group(1))
        cw = float(m.group(2))
        if ch <= 0 or cw <= 0:
            raise RenderError("Cannot get window size:  cannot get terminal cell size")
        return cw, ch
    finally:
        if fd is not None:
            try:
                if old_attrs is not None:
                    import termios

                    termios.tcsetattr(fd, termios.TCSANOW, old_attrs)
            except Exception:
                pass
            try:
                os.close(fd)
            except Exception:
                pass


def setup_terminal(rows: int) -> Tuple[float, float]:
    # This mirrors the byte structure in captures: hide cursor, reserve rows,
    # move back up, save cursor, query iTerm cell size.
    bwrite(b"\x1b[?25l")
    if rows < 0:
        # Mimic the observed Go panic closely enough for negative rows.
        raise RuntimeError("strings: negative Repeat count")
    bwrite(("\n" * rows).encode())
    bwrite(f"\x1b[{rows}A\x1b[s".encode())
    bwrite(b"\x1b]1337;ReportCellSize\x07")
    return read_iterm_cell_size()


def restore_after_frame(rows: int) -> None:
    bwrite(b"\x1b[?25h")
    bwrite(f"\x1b[{rows}B\n".encode())


def put_pixel(buf: bytearray, w: int, h: int, x: int, y: int, color: Tuple[int, int, int, int]) -> None:
    if x < 0 or y < 0 or x >= w or y >= h:
        return
    idx = (y * w + x) * 4
    buf[idx : idx + 4] = bytes(color)


def draw_line(buf: bytearray, w: int, h: int, x0: int, y0: int, x1: int, y1: int, color: Tuple[int, int, int, int]) -> None:
    dx = abs(x1 - x0)
    dy = -abs(y1 - y0)
    sx = 1 if x0 < x1 else -1
    sy = 1 if y0 < y1 else -1
    err = dx + dy
    x, y = x0, y0
    while True:
        # Slightly thicken lines for visibility.
        put_pixel(buf, w, h, x, y, color)
        put_pixel(buf, w, h, x, y + 1, color)
        if x == x1 and y == y1:
            break
        e2 = 2 * err
        if e2 >= dy:
            err += dy
            x += sx
        if e2 <= dx:
            err += dx
            y += sy


def make_png(width: int, height: int, graphs: List[Graph], steps: int) -> bytes:
    width = max(1, int(width))
    height = max(1, int(height))
    buf = bytearray([255, 255, 255, 255] * (width * height))
    # Background grid.
    grid = (232, 232, 232, 255)
    border = (180, 180, 180, 255)
    for x in range(0, width, max(1, width // 10)):
        for y in range(height):
            put_pixel(buf, width, height, x, y, grid)
    for y in range(0, height, max(1, height // 4)):
        for x in range(width):
            put_pixel(buf, width, height, x, y, grid)
    for x in range(width):
        put_pixel(buf, width, height, x, 0, border)
        put_pixel(buf, width, height, x, height - 1, border)
    for y in range(height):
        put_pixel(buf, width, height, 0, y, border)
        put_pixel(buf, width, height, width - 1, y, border)

    if graphs:
        gh = max(1, height // len(graphs))
    else:
        gh = height
    color_idx = 0
    for gi, graph in enumerate(graphs or [Graph([])]):
        y_top = gi * gh
        y_bot = height - 1 if gi == len(graphs) - 1 else min(height - 1, (gi + 1) * gh - 1)
        # border between graphs
        for x in range(width):
            put_pixel(buf, width, height, x, y_top, border)
            put_pixel(buf, width, height, x, y_bot, border)
        series = [f for f in graph.fields if f.is_series]
        vals = [v for f in series for v in f.values if math.isfinite(v)]
        if not vals:
            color_idx += len(series)
            continue
        mn = min(vals)
        mx = max(vals)
        if mx == mn:
            mx = mn + 1.0
        pad = max(2, min(16, width // 80))
        x0 = pad
        x1 = width - 1 - pad
        usable_h = max(1, y_bot - y_top - 2 * pad)
        usable_w = max(1, x1 - x0)
        for f in series:
            col = PALETTE[color_idx % len(PALETTE)]
            color_idx += 1
            vals_f = f.values[-max(1, steps) :]
            if not vals_f:
                continue
            pts: List[Tuple[int, int]] = []
            denom = max(1, steps - 1)
            # Align data at the right edge, as time-series plots do.
            start_index = steps - len(vals_f)
            for i, v in enumerate(vals_f):
                xi = x0 + int(round(((start_index + i) / denom) * usable_w))
                norm = (v - mn) / (mx - mn)
                yi = y_bot - pad - int(round(norm * usable_h))
                pts.append((xi, yi))
            if len(pts) == 1:
                x, y = pts[0]
                for dx in range(-2, 3):
                    for dy in range(-2, 3):
                        put_pixel(buf, width, height, x + dx, y + dy, col)
            else:
                for (xa, ya), (xb, yb) in zip(pts, pts[1:]):
                    draw_line(buf, width, height, xa, ya, xb, yb, col)
        # Markers in translucent red verticals.
        marker_color = (220, 0, 0, 255)
        for f in graph.fields:
            if not f.marker:
                continue
            marks = f.marks[-max(1, steps) :]
            denom = max(1, steps - 1)
            start_index = steps - len(marks)
            for i, mark in enumerate(marks):
                if mark:
                    xi = pad + int(round(((start_index + i) / denom) * max(1, width - 1 - 2 * pad)))
                    for y in range(y_top + 1, y_bot):
                        put_pixel(buf, width, height, xi, y, marker_color)

    raw = bytearray()
    stride = width * 4
    for y in range(height):
        raw.append(0)  # PNG filter type 0
        raw.extend(buf[y * stride : (y + 1) * stride])
    comp = zlib.compress(bytes(raw), 6)

    def chunk(typ: bytes, data: bytes) -> bytes:
        return struct.pack(">I", len(data)) + typ + data + struct.pack(">I", zlib.crc32(typ + data) & 0xFFFFFFFF)

    png = bytearray(b"\x89PNG\r\n\x1a\n")
    png.extend(chunk(b"IHDR", struct.pack(">IIBBBBB", width, height, 8, 6, 0, 0, 0)))
    png.extend(chunk(b"IDAT", comp))
    png.extend(chunk(b"IEND", b""))
    return bytes(png)


def render_frame(width_px: int, height_px: int, graphs: List[Graph], steps: int) -> None:
    png = make_png(width_px, height_px, graphs, max(1, steps)) if steps != 0 else b""
    b64 = base64.b64encode(png)
    prefix = f"\x1b]1337;File=preserveAspectRatio=1;width={int(width_px)}px;height={int(height_px)}px;inline=1:".encode()
    bwrite(prefix + b64 + b"\x07")
    bwrite(b"\x1b[u")


def validate_renderable(graphs: List[Graph], opts: Options) -> None:
    if opts.steps == 1:
        raise RenderError("cannot render graph: zero x-range delta; there needs to be at least (2) values")
    series_count = sum(1 for g in graphs for f in g.fields if f.is_series)
    if series_count == 0:
        raise RenderError("cannot render graph: please provide at least one series")


def run_render_once(graphs: List[Graph], opts: Options, rows: int, width_px: int, height_px: int) -> None:
    validate_renderable(graphs, opts)
    render_frame(width_px, height_px, graphs, opts.steps)


def main(argv: List[str]) -> int:
    supported, support_err = terminal_supported()

    try:
        opts, args = parse_flags(argv)
    except HelpRequested:
        ewrite(USAGE)
        return 0
    except FlagError as e:
        ewrite(str(e) + "\n")
        ewrite(USAGE)
        return 2

    if not supported:
        swrite(f"jplot:  {support_err}\n")
        return 1

    if len(args) == 0:
        ewrite(USAGE)
        return 1

    try:
        graphs = parse_specs(args)
    except ValueError as e:
        swrite(f"jplot:  Cannot parse spec:  {e}\n")
        return 1

    # Source availability check for interactive stdin.
    if not opts.url and sys.stdin.isatty():
        swrite("jplot:  neither --url nor stdin is provided\n")
        return 1

    # URL mode obtains the first sample before touching the terminal; all URL
    # errors observed are reported without cursor/image escape setup.
    if opts.url:
        try:
            obj = fetch_url_once(opts.url)
            apply_object(graphs, obj, opts.steps, opts.interval)
        except DataError as e:
            swrite(f"jplot:  Data source error:  {e}\n")
            return 1

    # Terminal size is fetched before reserving rows; failure has no escape
    # prefix in the observed binary.
    try:
        cols, term_rows = get_terminal_size_or_error()
    except RenderError as e:
        swrite(f"jplot:  {e}\n")
        return 1

    rows = opts.rows if opts.rows != 0 else term_rows
    try:
        cell_w, cell_h = setup_terminal(rows)
    except RuntimeError:
        # Close approximation of the Go panic for negative rows.
        swrite("panic: strings: negative Repeat count\n")
        return 2
    except RenderError as e:
        swrite(f"jplot:  {e}\n")
        return 1

    width_px = int(round(cols * cell_w))
    height_px = int(round(rows * cell_h))

    try:
        run_render_once(graphs, opts, rows, width_px, height_px)
    except RenderError as e:
        swrite(f"jplot:  {e}\n")
        return 1
    except Exception as e:
        # For unusual bad step values, preserve a panic-like failure.
        swrite(f"panic: {e}\n")
        return 2

    if opts.url:
        # Continue fetching/rendering periodically until signalled.  This is a
        # small live-mode approximation; it emits subsequent frames from the
        # saved cursor position just like captures of the original.
        next_time = time.time() + (opts.interval if opts.interval > 0 else 0.0)
        while running:
            delay = next_time - time.time()
            if delay > 0:
                time.sleep(min(delay, 0.1))
                continue
            try:
                obj = fetch_url_once(opts.url)
                apply_object(graphs, obj, opts.steps, opts.interval)
            except DataError as e:
                swrite(f"jplot:  Data source error:  {e}\n")
                return 1
            if not running:
                break
            bwrite(b"\x1b[s")
            try:
                render_frame(width_px, height_px, graphs, opts.steps)
            except Exception:
                pass
            interval = opts.interval if opts.interval > 0 else 1.0
            next_time += interval
        return 0

    # In stdin mode, the observed finite-pipe behavior draws the initial graph
    # and then reports data errors (if any) without another frame.
    try:
        process_stdin_records(graphs, opts)
    except DataError as e:
        swrite(f"jplot:  Data source error:  {e}\n")
        return 1

    restore_after_frame(rows)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
